#!/usr/bin/env python3
import json, sys
from pathlib import Path

def main():
    root = Path(sys.argv[1]) if len(sys.argv) > 1 else Path.cwd()
    blocking = []
    required = ["SKILL.md", "contracts/main_contract.md", "schemas/output.schema.json", "evals/eval_matrix.json"]
    for rel in required:
        if not (root / rel).exists():
            blocking.append(f"MISSING:{rel}")
    result = {"status": "PASS" if not blocking else "FAIL", "blocking_codes": blocking}
    print(json.dumps(result))
    return 0 if not blocking else 1

if __name__ == "__main__":
    raise SystemExit(main())
